# --- END PRESET LIBRARY ---

_library_cache = {}


def _addon_prefs():
    addon = bpy.context.preferences.addons.get(__name__)
    return addon.preferences if addon else None


def _library():
    """Preset library: a las_collision_presets.json override (add-on folder
    or the path in preferences) wins over the embedded copy."""
    prefs = _addon_prefs()
    candidates = []
    if prefs and prefs.presets_path:
        candidates.append(bpy.path.abspath(prefs.presets_path))
    candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "las_collision_presets.json"))
    source = "embedded"
    text = PRESET_LIBRARY_JSON
    for path in candidates:
        if path and os.path.isfile(path):
            source = path
            break
    if _library_cache.get("source") == source:
        return _library_cache["library"]
    if source != "embedded":
        with open(source, "r", encoding="utf-8") as stream:
            raw = json.load(stream)
        library = _normalise_library(raw)
    else:
        library = _normalise_library(json.loads(text))
    library["by_code"] = {int(p["code"], 16): p for p in library["presets"]}
    _library_cache.clear()
    _library_cache.update({"source": source, "library": library})
    return library


def _normalise_library(raw):
    """Accept both the full export-presets JSON and the compact embedded form."""
    def rows(items, keys):
        result = []
        for item in items:
            if isinstance(item, dict):
                result.append([item.get(key) for key in keys])
            else:
                result.append(list(item))
        return result
    return {
        "note": raw.get("note", ""),
        "materials": rows(raw.get("materials", []), ("value", "label", "effect", "confidence")),
        "surfaceClasses": rows(raw.get("surfaceClasses", []), ("value", "label", "effect", "confidence")),
        "areaTags": rows(raw.get("areaTags", []), ("mask", "label", "note")),
        "flags": rows(raw.get("flags", []), ("mask", "label", "note")),
        "presets": raw.get("presets", []),
    }


def _material_label(index):
    for value, label, _effect, _confidence in _library()["materials"]:
        if value == index:
            return label
    return f"Material {index}"


def _class_row(index):
    for row in _library()["surfaceClasses"]:
        if row[0] == index:
            return row
    return [index, f"F{index}", "", "unknown"]


def _describe_code(code):
    """Human description for any code, retail or composed."""
    preset = _library()["by_code"].get(code)
    if preset:
        return preset
    low6 = code & 0x3F
    surface_class = (code >> 6) & 0xF
    area = code & 0x1C00
    area_label = {0: "Dungeon", 0xC00: "Field", 0x1800: "House"}.get(area, f"Area 0x{area:X}")
    material_row = next((row for row in _library()["materials"] if row[0] == low6), [low6, f"Material {low6}", "", "unknown"])
    class_row = _class_row(surface_class)
    effects = [material_row[2]] + ([class_row[2]] if surface_class else [])
    return {
        "name": f"Custom 0x{code:X} ({material_row[1]}, {class_row[1]}, {area_label})",
        "code": f"0x{code:08X}",
        "category": "Custom",
        "materialName": material_row[1],
        "surfaceClassLabel": class_row[1],
        "areaTag": area_label,
        "tags": [],
        "effects": [effect for effect in effects if effect],
        "confidence": "not-in-retail",
        "triangles": 0,
        "rooms": 0,
        "exampleRoom": "",
        "recommended": False,
    }


