class LAS_PT_presets(bpy.types.Panel):
    bl_label = "Collision Presets"
    bl_idname = "LAS_PT_presets"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'LAS Collision'
    bl_parent_id = "LAS_PT_collision_panel"

    def draw(self, context):
        scene = context.scene
        layout = self.layout
        if not scene.las_presets:
            layout.operator(LAS_OT_refresh_presets.bl_idname, text="Load Presets", icon='FILE_REFRESH')
            return
        row = layout.row(align=True)
        row.prop(scene, "las_preset_category", text="")
        row.prop(scene, "las_preset_recommended_only", text="", icon='SOLO_ON')
        row.operator(LAS_OT_refresh_presets.bl_idname, text="", icon='FILE_REFRESH')
        layout.template_list("LAS_UL_presets", "", scene, "las_presets", scene, "las_preset_index", rows=8)
        if 0 <= scene.las_preset_index < len(scene.las_presets):
            item = scene.las_presets[scene.las_preset_index]
            preset = _describe_code(item.code)
            box = layout.box()
            box.label(text=f"0x{item.code:08X}  ·  {preset.get('confidence', '')}", icon=CONFIDENCE_ICONS.get(item.confidence, 'DOT'))
            for effect in preset.get("effects", []):
                box.label(text=effect)
            if preset.get("exampleRoom"):
                box.label(text=f"Used in {preset.get('rooms', 0)} rooms, e.g. {preset['exampleRoom']}")
        layout.operator(LAS_OT_assign_preset.bl_idname, icon='MATERIAL')
        layout.label(text="Edit Mode: selected faces · Object Mode: whole objects")


class LAS_PT_compose(bpy.types.Panel):
    bl_label = "Advanced: Compose Code"
    bl_idname = "LAS_PT_compose"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'LAS Collision'
    bl_parent_id = "LAS_PT_collision_panel"
