    def draw(self, context):
        scene = context.scene
        layout = self.layout
        layout.prop(scene, "las_compose_material", text="Surface")
        layout.prop(scene, "las_compose_class", text="Behaviour")
        layout.prop(scene, "las_compose_area", text="Area tag")
        row = layout.row(align=True)
        row.prop(scene, "las_compose_flag_4000", text="0x4000", toggle=True)
        row.prop(scene, "las_compose_flag_40000", text="0x40000", toggle=True)
        row.prop(scene, "las_compose_flag_80000", text="0x80000", toggle=True)
        code = _composed_code(scene)
        preset = _library()["by_code"].get(code)
        box = layout.box()
