CLASSES = (
    LAS_PresetItem,
    LAS_UL_presets,
    LAS_OT_import_cidb,
    LAS_OT_export_collision,
    LAS_OT_bake,
    LAS_OT_assign_preset,
    LAS_OT_refresh_presets,
    LAS_OT_assign_composed,
    LAS_OT_add_primitive,
    LAS_PT_collision_panel,
    LAS_PT_presets,
    LAS_PT_compose,
    LAS_PT_primitives,
    LAS_PT_bake,
    LAS_AddonPreferences,
)

SCENE_PROPERTIES = {
    "las_presets": lambda: CollectionProperty(type=LAS_PresetItem),
    "las_preset_index": lambda: IntProperty(default=0),
    "las_preset_category": lambda: EnumProperty(name="Category", items=CATEGORY_ITEMS, default='ALL'),
    "las_preset_recommended_only": lambda: BoolProperty(name="Recommended only", default=False,
                                                        description="Show only the most used code per category/material/area"),
    "las_compose_material": lambda: EnumProperty(name="Surface", items=_material_enum),
    "las_compose_class": lambda: EnumProperty(name="Behaviour", items=_class_enum),
    "las_compose_area": lambda: EnumProperty(name="Area tag", items=_area_enum),
    "las_compose_flag_4000": lambda: BoolProperty(name="Tag 0x4000"),
    "las_compose_flag_40000": lambda: BoolProperty(name="Tag 0x40000"),
    "las_compose_flag_80000": lambda: BoolProperty(name="Autojump tag 0x80000"),
    "las_bake_mode": lambda: EnumProperty(name="Bake mode", items=BAKE_MODES, default='PHYSX'),
    "las_bake_template": lambda: StringProperty(name="Template CIDB", subtype='FILE_PATH'),
    "las_bake_output": lambda: StringProperty(name="Output CIDB", subtype='FILE_PATH'),
    "las_bake_log": lambda: StringProperty(name="Last bake log"),
}


def register():
    for cls in CLASSES:
        bpy.utils.register_class(cls)
    for name, factory in SCENE_PROPERTIES.items():
        setattr(bpy.types.Scene, name, factory())
    bpy.types.TOPBAR_MT_file_import.append(_menu_import)
    bpy.types.TOPBAR_MT_file_export.append(_menu_export)


def unregister():
    bpy.types.TOPBAR_MT_file_import.remove(_menu_import)
    bpy.types.TOPBAR_MT_file_export.remove(_menu_export)
    for name in SCENE_PROPERTIES:
        delattr(bpy.types.Scene, name)
    for cls in reversed(CLASSES):
        bpy.utils.unregister_class(cls)


if __name__ == "__main__":
    register()
